import React, { useState, useEffect } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import {
  Box,
  Typography,
  TextField,
  Button,
  Avatar,
  IconButton,
  Divider,
  Paper,
  CircularProgress,
  Tabs,
  Tab,
  Container,
  Snackbar,
  Alert,
  Menu,
  MenuItem,
  ListItemIcon,
  ListItemText
} from '@mui/material';
import {
  ThumbUp as ThumbUpIcon,
  ThumbUpOutlined as ThumbUpOutlinedIcon,
  Reply as ReplyIcon,
  MoreVert as MoreVertIcon,
  Delete as DeleteIcon,
  Edit as EditIcon
} from '@mui/icons-material';
import { useAuth } from '../context/AuthContext';
import { useWebSocket } from '../context/WebSocketContext';
import { fetchPosts, likePost, likePostAsync, addComment } from '../features/community/communitySlice';
import api from '../utils/api';

function TabPanel({ children, value, index, ...other }) {
  return (
    <div
      role="tabpanel"
      hidden={value !== index}
      id={`simple-tabpanel-${index}`}
      aria-labelledby={`simple-tab-${index}`}
      {...other}
    >
      {value === index && (
        <Box sx={{ p: 3 }}>
          {children}
        </Box>
      )}
    </div>
  );
}

function a11yProps(index) {
  return {
    id: `simple-tab-${index}`,
    'aria-controls': `simple-tabpanel-${index}`,
  };
}

const Home = () => {
  const { user } = useAuth();
  const { isConnected } = useWebSocket();
  const dispatch = useDispatch();
  const { posts, status, error } = useSelector((state) => state.community);
  const [activeTab, setActiveTab] = useState(0);
  const [snackbar, setSnackbar] = useState({ open: false, message: '', severity: 'success' });
  const [commentContent, setCommentContent] = useState('');
  const [replyingTo, setReplyingTo] = useState(null);
  const [editingComment, setEditingComment] = useState(null);
  const [commentAnchorEl, setCommentAnchorEl] = useState(null);
  const [selectedComment, setSelectedComment] = useState(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        await dispatch(fetchPosts());
      } catch (err) {
        console.error('Error fetching posts:', err);
        setSnackbar({ open: true, message: 'Failed to load posts', severity: 'error' });
      }
    };
    fetchData();
  }, [dispatch]);

  const handleTabChange = (event, newValue) => {
    setActiveTab(newValue);
  };

  const handleLike = async (postId) => {
    try {
      // Generate a unique ID for anonymous user if not exists
      let userId = localStorage.getItem('anonymousUserId');
      if (!userId) {
        userId = `anon_${Math.random().toString(36).substr(2, 9)}`;
        localStorage.setItem('anonymousUserId', userId);
      }
      
      // Optimistic UI update
      dispatch(likePost({ postId, userId }));
      
      // Make the actual API call with the anonymous user ID
      await dispatch(likePostAsync({ postId, userId })).unwrap();
    } catch (err) {
      console.error('Error liking post:', err);
      setSnackbar({ 
        open: true, 
        message: err.message || 'Failed to like post', 
        severity: 'error' 
      });
    }
  };

  const handlePostSubmit = async (content) => {
    if (!content.trim()) return;
    
    try {
      // Generate a unique ID for anonymous user if not exists
      let userId = user?._id;
      let isAnonymous = false;
      
      if (!userId) {
        userId = localStorage.getItem('anonymousUserId');
        if (!userId) {
          userId = `anon_${Math.random().toString(36).substr(2, 9)}`;
          localStorage.setItem('anonymousUserId', userId);
        }
        isAnonymous = true;
      }
      
      // Make the API call to create the post with user info
      await api.post('/thoughts', { 
        content,
        user: {
          _id: userId,
          username: isAnonymous ? `Anonymous_${userId.substring(0, 6)}` : 'Anonymous',
          isAnonymous
        }
      });
      
      // Clear the input and show success message
      setCommentContent('');
      setSnackbar({ 
        open: true, 
        message: 'Post created successfully!', 
        severity: 'success' 
      });
      
      // Refresh the posts list
      dispatch(fetchPosts());
    } catch (err) {
      console.error('Error creating post:', err);
      const errorMessage = err.response?.data?.message || err.message || 'Failed to create post';
      
      setSnackbar({ 
        open: true, 
        message: errorMessage, 
        severity: 'error' 
      });
      if (err.response?.status === 401) {
        setSnackbar({ 
          open: true, 
          message: 'Your session has expired. Please log in again.', 
          severity: 'error'
        });
        // Redirect after a short delay to show the message
        setTimeout(() => {
          localStorage.removeItem('token');
          window.location.href = '/login';
        }, 1500);
      } else {
        setSnackbar({ 
          open: true, 
          message: errorMessage, 
          severity: 'error' 
        });
      }
    }
  };

  const handleCommentSubmit = async (postId, content, commentId = null) => {
    if (!content.trim()) return;
    
    try {
      if (commentId) {
        // Update existing comment
        await api.put(`/thoughts/${postId}/comments/${commentId}`, { content });
        setSnackbar({ open: true, message: 'Comment updated!', severity: 'success' });
        setEditingComment(null);
      } else {
        // Add new comment
        await dispatch(addComment({ postId, content })).unwrap();
        setReplyingTo(null);
        setSnackbar({ open: true, message: 'Comment added!', severity: 'success' });
      }
      setCommentContent('');
      dispatch(fetchPosts());
    } catch (err) {
      console.error('Error saving comment:', err);
      setSnackbar({ 
        open: true, 
        message: err.response?.data?.message || 'Failed to save comment', 
        severity: 'error' 
      });
    }
  };

  const handleCommentMenuClick = (event, comment, postId) => {
    event.stopPropagation();
    setCommentAnchorEl(event.currentTarget);
    setSelectedComment({ ...comment, postId });
  };

  const handleCommentMenuClose = () => {
    setCommentAnchorEl(null);
    setSelectedComment(null);
  };

  const handleEditComment = () => {
    if (selectedComment) {
      setCommentContent(selectedComment.content);
      setEditingComment(selectedComment._id);
      handleCommentMenuClose();
    }
  };

  const handleDeleteComment = async () => {
    if (!selectedComment) return;
    
    try {
      await api.delete(`/thoughts/${selectedComment.postId}/comments/${selectedComment._id}`);
      setSnackbar({ open: true, message: 'Comment deleted!', severity: 'success' });
      dispatch(fetchPosts());
    } catch (err) {
      console.error('Error deleting comment:', err);
      setSnackbar({ 
        open: true, 
        message: err.response?.data?.message || 'Failed to delete comment', 
        severity: 'error' 
      });
    } finally {
      handleCommentMenuClose();
    }
  };

  const isCommentOwner = (comment) => {
  if (!comment || !comment.user) return false;
  const currentUserId = user?._id || localStorage.getItem('anonymousUserId');
  const commentUserId = typeof comment.user === 'object' ? comment.user._id : comment.user;
  return commentUserId === currentUserId;
};

  return (
    <Container maxWidth="md" sx={{ py: 3 }}>
      <Box sx={{ width: '100%' }}>
        <Box sx={{ borderBottom: 1, borderColor: 'divider' }}>
          <Tabs 
            value={activeTab} 
            onChange={handleTabChange} 
            aria-label="home tabs"
            variant="fullWidth"
          >
            <Tab label="Posts" {...a11yProps(0)} />
            <Tab label="Polls" {...a11yProps(1)} />
          </Tabs>
        </Box>

        <TabPanel value={activeTab} index={0}>
          {/* Post Form */}
          <Paper sx={{ p: 2, mb: 3, borderRadius: 2 }}>
            <Box display="flex" gap={2}>
              <Avatar 
                src={user?.avatar} 
                alt={user?.username}
                sx={{ width: 48, height: 48 }}
              />
              <Box flex={1}>
                <Typography variant="subtitle2" color="text.secondary" mb={1}>
                  Share your thoughts...
                </Typography>
                <TextField
                  fullWidth
                  multiline
                  rows={3}
                  variant="outlined"
                  placeholder="What's on your mind?"
                  value={commentContent}
                  onChange={(e) => setCommentContent(e.target.value)}
                  sx={{ mb: 2 }}
                />
                <Box display="flex" justifyContent="flex-end">
                  <Button
                    variant="contained"
                    color="primary"
                    disabled={!commentContent.trim() || status === 'loading'}
                    onClick={() => handlePostSubmit(commentContent)}
                  >
                    {status === 'loading' ? 'Posting...' : 'Post'}
                  </Button>
                </Box>
              </Box>
            </Box>
          </Paper>

          {/* Posts List */}
          {status === 'loading' ? (
            <Box display="flex" justifyContent="center" my={4}>
              <CircularProgress />
            </Box>
          ) : error ? (
            <Alert severity="error" sx={{ mb: 2 }}>
              {error}
            </Alert>
          ) : posts.length === 0 ? (
            <Paper elevation={2} sx={{ p: 3, textAlign: 'center' }}>
              <Typography variant="h6" color="textSecondary" gutterBottom>
                No posts yet
              </Typography>
              <Typography variant="body2" color="textSecondary">
                Be the first to share your thoughts!
              </Typography>
            </Paper>
          ) : (
            posts.map((post) => (
              <Paper key={post._id} sx={{ p: 3, mb: 3, borderRadius: 2 }}>
                {/* Post header */}
                <Box display="flex" justifyContent="space-between" alignItems="flex-start" mb={2}>
                  <Box display="flex" alignItems="center">
                    <Avatar 
                      src={post.user?.avatar} 
                      alt={post.user?.username}
                      sx={{ width: 40, height: 40 }}
                    />
                    <Box ml={2}>
                      <Typography variant="subtitle1" fontWeight="bold">
                        {post.user?.username || 'Unknown User'}
                      </Typography>
                      <Typography variant="caption" color="text.secondary">
                        {new Date(post.createdAt).toLocaleString()}
                      </Typography>
                    </Box>
                  </Box>
                  
                  {user?._id === post.user?._id && (
                    <IconButton size="small">
                      <MoreVertIcon />
                    </IconButton>
                  )}
                </Box>
                
                {/* Post content */}
                <Typography paragraph sx={{ whiteSpace: 'pre-line', mb: 2 }}>
                  {post.content}
                </Typography>
                
                <Divider sx={{ my: 1 }} />
                
                {/* Post actions */}
                <Box display="flex" justifyContent="space-between" mt={1}>
                  <Button
                    startIcon={
                      post.likes?.includes(user?._id) ? (
                        <ThumbUpIcon color="primary" />
                      ) : (
                        <ThumbUpOutlinedIcon />
                      )
                    }
                    onClick={() => handleLike(post._id)}
                    size="small"
                    sx={{ color: 'text.secondary' }}
                  >
                    {post.likes?.length || 0} Likes
                  </Button>
                  
                  <Button
                    startIcon={<ReplyIcon />}
                    onClick={() => setReplyingTo(prev => prev === post._id ? null : post._id)}
                    size="small"
                    sx={{ color: 'text.secondary' }}
                  >
                    {replyingTo === post._id ? 'Cancel' : 'Comment'}
                  </Button>
                </Box>
                
                {/* Comments List */}
                {post.comments?.map((comment) => (
                  <Box key={comment._id} sx={{ mt: 2, pl: 2, borderLeft: '2px solid #e0e0e0' }}>
                    <Box display="flex" justifyContent="space-between" alignItems="flex-start">
                      <Box display="flex" alignItems="center" mb={1}>
                        <Avatar 
                          src={comment.user?.avatar} 
                          sx={{ width: 24, height: 24, mr: 1 }}
                        />
                        <Typography variant="subtitle2" fontWeight="bold">
                          {comment.user?.username || 'Anonymous'}
                        </Typography>
                        {isCommentOwner(comment) && (
                          <IconButton 
                            size="small" 
                            onClick={(e) => handleCommentMenuClick(e, comment, post._id)}
                            sx={{ ml: 'auto' }}
                          >
                            <MoreVertIcon fontSize="small" />
                          </IconButton>
                        )}
                      </Box>
                    </Box>
                    {editingComment === comment._id ? (
                      <Box display="flex" flexDirection="column" gap={1} mt={1}>
                        <TextField
                          fullWidth
                          size="small"
                          value={commentContent}
                          onChange={(e) => setCommentContent(e.target.value)}
                          autoFocus
                        />
                        <Box display="flex" justifyContent="flex-end" gap={1}>
                          <Button 
                            size="small" 
                            onClick={() => {
                              setEditingComment(null);
                              setCommentContent('');
                            }}
                          >
                            Cancel
                          </Button>
                          <Button 
                            variant="contained" 
                            size="small"
                            onClick={() => handleCommentSubmit(post._id, commentContent, comment._id)}
                            disabled={!commentContent.trim()}
                          >
                            Update
                          </Button>
                        </Box>
                      </Box>
                    ) : (
                      <Typography variant="body2" sx={{ whiteSpace: 'pre-line' }}>
                        {comment.content}
                      </Typography>
                    )}
                  </Box>
                ))}
                
                {/* Comment input */}
                {replyingTo === post._id && (
                  <Box mt={2} mb={1}>
                    <TextField
                      fullWidth
                      size="small"
                      placeholder="Write a comment..."
                      value={commentContent}
                      onChange={(e) => setCommentContent(e.target.value)}
                      onKeyDown={(e) => {
                        if (e.key === 'Enter' && !e.shiftKey) {
                          e.preventDefault();
                          if (commentContent.trim()) {
                            handleCommentSubmit(post._id, commentContent);
                          }
                        }
                      }}
                      multiline
                      maxRows={4}
                    />
                    <Box display="flex" justifyContent="flex-end" mt={1} gap={1}>
                      <Button 
                        size="small" 
                        variant="outlined" 
                        onClick={() => setReplyingTo(null)}
                      >
                        Cancel
                      </Button>
                      <Button 
                        size="small" 
                        variant="contained" 
                        onClick={() => handleCommentSubmit(post._id, commentContent)}
                        disabled={!commentContent.trim()}
                      >
                        Comment
                      </Button>
                    </Box>
                  </Box>
                )}
              </Paper>
            ))
          )}
        </TabPanel>

        <TabPanel value={activeTab} index={1}>
          <Paper sx={{ p: 3, textAlign: 'center' }}>
            <Typography variant="h6" gutterBottom>
              Polls
            </Typography>
            <Typography color="textSecondary">
              Polls functionality coming soon!
            </Typography>
          </Paper>
        </TabPanel>
      </Box>

      <Snackbar
        open={snackbar.open}
        autoHideDuration={6000}
        onClose={() => setSnackbar(prev => ({ ...prev, open: false }))}
      >
        <Alert 
          onClose={() => setSnackbar(prev => ({ ...prev, open: false }))} 
          severity={snackbar.severity}
          sx={{ width: '100%' }}
        >
          {snackbar.message}
        </Alert>
      </Snackbar>
    </Container>
  );
};

export default Home;
